    pub struct OpenShadowProcSkel<'a> {
        pub obj: libbpf_rs::OpenObject,
        pub struct_ops: shadow_proc_types::struct_ops,
        skel_config: libbpf_rs::__internal_skel::ObjectSkeletonConfig<'a>,
    }

    impl<'a> OpenSkel for OpenShadowProcSkel<'a> {
        type Output = ShadowProcSkel<'a>;
        fn load(mut self) -> libbpf_rs::Result<ShadowProcSkel<'a>> {
            let ret = unsafe { libbpf_sys::bpf_object__load_skeleton(self.skel_config.get()) };
            if ret != 0 {
                return Err(libbpf_rs::Error::from_raw_os_error(-ret));
            }

            let obj = unsafe { libbpf_rs::Object::from_ptr(self.obj.take_ptr())? };

            Ok(ShadowProcSkel {
                obj,
                struct_ops: self.struct_ops,
                skel_config: self.skel_config,
                links: ShadowProcLinks::default(),
            })
        }

        fn open_object(&self) -> &libbpf_rs::OpenObject {
            &self.obj
        }

        fn open_object_mut(&mut self) -> &mut libbpf_rs::OpenObject {
            &mut self.obj
        }
    }
